import type { BankQuestion } from "@/lib/bank";

/** Molecular Basis of Inheritance (Biology (NEET)): 100 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-molecular-basis-inheritance-1","question":"The double helix model of DNA was proposed in 1953 by:","options":["Watson and Crick","Meselson and Stahl","Hershey and Chase","Jacob and Monod"],"answer":0,"explanation":"James Watson and Francis Crick proposed the double helix in 1953, using Wilkins and Franklin's X-ray diffraction data and Chargaff's base-pairing rules.","difficulty":"easy"},
  {"id":"bio-molecular-basis-inheritance-2","question":"In RNA, adenine pairs with:","options":["Thymine","Guanine","Uracil","Cytosine"],"answer":2,"explanation":"RNA contains uracil in place of thymine, so adenine pairs with uracil (A-U) in RNA structures and in codon-anticodon pairing.","difficulty":"easy"},
  {"id":"bio-molecular-basis-inheritance-3","question":"The enzyme that joins the discontinuously synthesised Okazaki fragments is:","options":["DNA polymerase","Helicase","DNA ligase","Primase"],"answer":2,"explanation":"On the lagging template, DNA is made in short fragments (Okazaki fragments) that DNA ligase later joins into a continuous strand.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-4","question":"The total length of DNA in a typical human diploid cell (6.6 × 10⁹ bp, 0.34 nm per base pair) is approximately:","options":["2.2 m","0.22 m","22 m","1.36 mm"],"answer":0,"explanation":"6.6 × 10⁹ × 0.34 × 10⁻⁹ m = 2.244 m, about 2.2 metres. (1.36 mm is the length of the E. coli chromosome of 4.6 × 10⁶ bp.)","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-5","question":"In the Hershey-Chase experiment, bacteriophage DNA and protein were labelled respectively with:","options":["³⁵S and ³²P","¹⁵N and ¹⁴N","³²P and ³⁵S","³H and ¹⁴C"],"answer":2,"explanation":"DNA contains phosphorus but no sulphur, protein contains sulphur but no phosphorus. Radioactive ³²P entered the bacteria (DNA is the genetic material); ³⁵S stayed in the phage coats outside.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-6","question":"Of the 64 codons, how many specify amino acids?","options":["64","61","60","20"],"answer":1,"explanation":"61 codons code for amino acids; UAA, UAG and UGA are stop codons. AUG has a dual function: it codes for methionine and also initiates translation.","difficulty":"moderate"},
  {"id":"bio-molecular-basis-inheritance-7","question":"In the lac operon, the y gene codes for:","options":["β-galactosidase","Repressor","Transacetylase","Permease"],"answer":3,"explanation":"z codes β-galactosidase (hydrolyses lactose), y codes permease (increases lactose uptake), a codes transacetylase; the i gene, outside the structural genes, codes the repressor.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-8","question":"The 'transforming principle' observed by Griffith (1928) was biochemically identified as DNA by:","options":["Avery, MacLeod and McCarty","Watson and Crick","Hershey and Chase","Meselson and Stahl"],"answer":0,"explanation":"Avery, MacLeod and McCarty (1933-44) showed that only DNase, not protease or RNase, destroyed transformation, so the transforming principle was DNA.","difficulty":"moderate"},
  {"id":"bio-molecular-basis-inheritance-9","question":"DNA fingerprinting, developed by Alec Jeffreys, is based on polymorphism in:","options":["Exons of structural genes","Variable Number of Tandem Repeats (VNTR)","Promoter sequences","Ribosomal RNA genes"],"answer":1,"explanation":"VNTRs are satellite DNA repeats whose copy number varies from person to person; a labelled VNTR probe reveals a unique banding pattern after Southern blotting.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-10","question":"In B-DNA the pitch of the helix and the number of base pairs per turn are respectively:","options":["3.4 nm and 10","0.34 nm and 10","3.4 nm and 20","2 nm and 10"],"answer":0,"explanation":"One turn (pitch) is 3.4 nm and contains roughly 10 bp, so adjacent base pairs are 0.34 nm apart; the helix diameter is 2 nm (20 Å).","difficulty":"hard"},
  {"id":"bio-molecular-basis-inheritance-11","question":"According to the Human Genome Project, the chromosome with the most genes and the one with the fewest genes are respectively:","options":["Chromosome 1 (2968) and Y (231)","Chromosome X (2968) and 21 (231)","Chromosome 1 (231) and Y (2968)","Chromosome 2 (2968) and 22 (231)"],"answer":0,"explanation":"HGP found chromosome 1 carries the most genes (2968) and the Y chromosome the fewest (231), among about 30,000 genes in total.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-12","question":"In the Meselson-Stahl experiment, after ¹⁵N-labelled E. coli was transferred to ¹⁴N medium for two generations (40 minutes), the DNA was:","options":["All hybrid (¹⁵N-¹⁴N)","All light","Half heavy and half light","Half hybrid and half light (¹⁴N-¹⁴N)"],"answer":3,"explanation":"After one generation (20 min) all DNA is hybrid; after the second round each hybrid molecule yields one hybrid and one light molecule, so 50% hybrid and 50% light. This proved semi-conservative replication.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-13","question":"In eukaryotes, RNA polymerase III transcribes:","options":["Only rRNA (28S, 18S, 5.8S)","Precursor of mRNA (hnRNA)","tRNA, 5S rRNA and snRNA","Only mRNA and snRNA"],"answer":2,"explanation":"Pol I makes 28S, 18S and 5.8S rRNA; Pol II makes hnRNA (precursor of mRNA); Pol III makes tRNA, 5S rRNA and snRNAs.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-14","question":"Capping of hnRNA involves adding methyl guanosine triphosphate to the ______ end, while tailing adds about ______ adenylate residues to the ______ end.","options":["5', 200 to 300, 3'","3', 200 to 300, 5'","5', 20 to 30, 3'","3', 20 to 30, 5'"],"answer":0,"explanation":"The cap (methyl guanosine triphosphate) is added at the 5' end and a poly-A tail of 200 to 300 adenylate residues at the 3' end, independent of the template; splicing removes introns.","difficulty":"hard"},
  {"id":"bio-molecular-basis-inheritance-15","question":"A nucleosome contains a histone octamer wrapped by about ______ base pairs of DNA. Histones are rich in ______.","options":["200; lysine and arginine","146; aspartate and glutamate","200; aspartate and glutamate","100; lysine and arginine"],"answer":0,"explanation":"NCERT: a typical nucleosome contains 200 bp of DNA helix wound around a histone octamer. Histones are positively charged because of their abundant basic residues lysine and arginine, letting them bind negatively charged DNA.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-16","question":"The rate of polymerisation by E. coli DNA polymerase is about 2000 bp per second, yet the whole chromosome (4.6 × 10⁶ bp) replicates in about:","options":["38 minutes","4 minutes","18 minutes","60 minutes"],"answer":2,"explanation":"NCERT states the E. coli chromosome completes replication within 18 minutes; the enzyme's speed and bidirectional synthesis from the origin make this possible.","difficulty":"hard"},
  {"id":"bio-molecular-basis-inheritance-17","question":"If a double-stranded DNA sample contains 20% adenine, the percentage of guanine is:","options":["20%","30%","40%","60%"],"answer":1,"explanation":"By Chargaff's rule A = T and G = C. A = T = 20% accounts for 40%; the remaining 60% is G + C, so G = C = 30%.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-18","question":"During translation, the catalyst for peptide bond formation in the ribosome is:","options":["Aminoacyl tRNA synthetase","A protein of the small subunit","Ribosomal RNA of the large subunit (a ribozyme)","GTP"],"answer":2,"explanation":"NCERT: the rRNA of the larger subunit acts as the catalyst (peptidyl transferase) for peptide bond formation, making the ribosome a ribozyme. Aminoacyl tRNA synthetases charge tRNAs before translation.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-19","question":"How many of the following statements about the genetic code are correct?\n(i) The code is degenerate: some amino acids are coded by more than one codon.\n(ii) The code is unambiguous: one codon codes for only one amino acid.\n(iii) The code is read in a contiguous manner without punctuation.\n(iv) The code is strictly universal with no known exceptions.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) is wrong: the code is nearly universal, but mitochondrial codons and some protozoans are exceptions.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-20","question":"Which statement about the lac operon is INCORRECT?","options":["Lactose (allolactose) acts as the inducer","Regulation of the lac operon by the repressor is negative regulation","In the absence of inducer the repressor binds the operator and blocks RNA polymerase","The i gene codes for the inducer"],"answer":3,"explanation":"The i gene codes for the repressor, not the inducer. The inducer is lactose, which inactivates the repressor so that transcription of z, y and a can proceed.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-21","question":"Match the scientist with the contribution.\nList I: (A) Taylor and colleagues (B) Nirenberg (C) Severo Ochoa (D) Jacob and Monod\nList II: (1) Polynucleotide phosphorylase enabling RNA synthesis in vitro (2) Lac operon model (3) Semi-conservative replication shown in Vicia faba with radioactive thymidine (4) Cell-free protein synthesis to decode codons","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-1, B-4, C-3, D-2"],"answer":0,"explanation":"Taylor (1958) used radioactive thymidine in Vicia faba; Nirenberg's cell-free system decoded codons; Ochoa's polynucleotide phosphorylase made RNA with defined sequences; Jacob and Monod proposed the operon.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-22","question":"How many of the following findings of the Human Genome Project are correct?\n(i) The human genome contains about 3164.7 million base pairs.\n(ii) Less than 2% of the genome codes for proteins.\n(iii) The average gene is 3000 bp long, the largest (dystrophin) being 2.4 million bp.\n(iv) About 1.4 million single nucleotide polymorphisms were identified.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are stated HGP findings (project 1990-2003). Also, any two humans are 99.9% identical in sequence and over 50% of discovered genes have unknown function.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-23","question":"Arrange the steps of DNA fingerprinting in the correct order.\n(i) Hybridisation with labelled VNTR probe\n(ii) Separation of fragments by electrophoresis\n(iii) Digestion of DNA by restriction endonucleases\n(iv) Transfer to a synthetic membrane (Southern blotting)\n(v) Detection by autoradiography","options":["(iii), (ii), (iv), (i), (v)","(ii), (iii), (iv), (i), (v)","(iii), (iv), (ii), (i), (v)","(iii), (ii), (i), (iv), (v)"],"answer":0,"explanation":"After isolation, DNA is digested with restriction enzymes, separated by electrophoresis, blotted on to nitrocellulose or nylon, hybridised with the labelled VNTR probe and finally detected by autoradiography.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-24","question":"If the template strand of a transcription unit reads 3'-TACGGT-5', the mRNA transcribed from it is:","options":["5'-AUGCCA-3'","5'-ATGCCA-3'","3'-AUGCCA-5'","5'-UACGGU-3'"],"answer":0,"explanation":"RNA polymerase reads the template 3' → 5' and makes RNA 5' → 3' complementary to it, with U for A: 5'-AUGCCA-3'. This equals the coding strand sequence with T replaced by U.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-25","question":"A double-stranded DNA segment of 1000 base pairs contains 20% adenine. The total number of hydrogen bonds in the segment is:","options":["1200","1300","2000","1500"],"answer":1,"explanation":"A = T = 20% → 200 A-T pairs × 2 bonds = 400. G = C = 30% → 300 G-C pairs × 3 bonds = 900. Total = 1300.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-26","question":"How many of the following statements about DNA replication are correct?\n(i) Synthesis is continuous on the template with 3' → 5' polarity and discontinuous on the other.\n(ii) Deoxyribonucleoside triphosphates act as substrates and also provide energy.\n(iii) In eukaryotes replication occurs during the S phase.\n(iv) Replication begins at any random point on the DNA.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) is false: replication starts only at a definite region called the origin of replication.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-27","question":"Assertion (A): DNA is a better genetic material than RNA for long-term storage of information.\nReason (R): The absence of the 2'-OH group and the presence of thymine in place of uracil make DNA chemically more stable and less reactive than RNA.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. RNA, with its reactive 2'-OH, is labile and mutates faster; thymine also makes DNA more stable. That is why RNA, the first genetic material, gave way to DNA for storage while RNA kept the catalytic and messenger roles.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-28","question":"Which statement about eukaryotic transcription is INCORRECT?","options":["The primary transcript (hnRNA) contains both exons and introns","Introns are removed by splicing and exons are joined","Transcription and translation are coupled, as in bacteria","snurps (snRNPs) are involved in splicing"],"answer":2,"explanation":"In eukaryotes transcription (nucleus) and translation (cytoplasm) are separated in space and time; hnRNA must be processed and exported first. Coupling of the two occurs only in bacteria.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-29","question":"How many of the following statements about translation are correct?\n(i) Charging of tRNA (aminoacylation) requires ATP.\n(ii) There is a special initiator tRNA.\n(iii) There are specific tRNAs for the stop codons.\n(iv) Untranslated regions (UTRs) are present at both 5' and 3' ends of the mRNA.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iv) are correct. (iii) is false: no tRNA exists for UAA, UAG and UGA, which is why translation stops there.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-30","question":"Match the bacteriophage or organism with its genome size.\nList I: (A) Bacteriophage φ×174 (B) Bacteriophage lambda (C) Escherichia coli (D) Human haploid genome\nList II: (1) 48,502 bp (2) 3.3 × 10⁹ bp (3) 5386 nucleotides (4) 4.6 × 10⁶ bp","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-4, B-1, C-3, D-2"],"answer":0,"explanation":"φ×174 has 5386 nucleotides, lambda 48,502 bp, E. coli 4.6 × 10⁶ bp, and the human haploid genome 3.3 × 10⁹ bp (6.6 × 10⁹ bp per diploid cell).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-31","question":"The process of copying genetic information from one strand of DNA into RNA is called:","options":["Replication","Translation","Reverse transcription","Transcription"],"answer":3,"explanation":"Transcription copies DNA into RNA; translation uses the mRNA to make a polypeptide; replication copies DNA into DNA.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-32","question":"In bacteria, the RNA polymerase associates transiently with the rho (ρ) factor in order to:","options":["Add the poly-A tail","Terminate transcription","Splice introns","Initiate transcription"],"answer":1,"explanation":"The σ (sigma) factor helps initiation and the ρ (rho) factor helps termination of transcription in bacteria.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-33","question":"During splicing of the hnRNA in eukaryotes:","options":["Exons are removed and introns are joined","Introns are removed and exons are joined in a defined order","A cap is added at the 3' end","The RNA is translated in the nucleus"],"answer":1,"explanation":"Exons appear in mature RNA, whereas introns are intervening sequences removed by splicing.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-34","question":"The chromatin that is loosely packed, stains light and is transcriptionally active is called:","options":["Satellite DNA","Heterochromatin","Euchromatin","Nucleoid"],"answer":2,"explanation":"Loosely packed euchromatin is transcriptionally active; densely packed, dark-staining heterochromatin is inactive.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-35","question":"Packaging of chromatin at a higher level, beyond the beads-on-string structure, requires an additional set of proteins called:","options":["Histone octamers only","Non-histone chromosomal (NHC) proteins","Aminoacyl tRNA synthetases","Sigma factors"],"answer":1,"explanation":"Nucleosomes form the beads-on-string chromatin fibres, which coil further into chromatin fibres and chromosomes with the help of NHC proteins.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-36","question":"Polycistronic structural genes are mostly found in:","options":["Bacteria (prokaryotes)","Eukaryotes","Mitochondria of animals only","RNA viruses only"],"answer":0,"explanation":"In eukaryotes structural genes are mostly monocistronic; in bacteria and prokaryotes the structural gene in a transcription unit is generally polycistronic, as in the lac operon.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-37","question":"In the experiments of Avery, MacLeod and McCarty, transformation of R strain into S strain was inhibited only by:","options":["RNase","DNase","Lipase","Protease"],"answer":1,"explanation":"Proteases and RNases did not affect transformation, but DNase did, showing that the transforming substance was DNA.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-38","question":"Insertion of three bases (one codon) into the coding part of a gene usually:","options":["Has no effect on the protein at all","Always produces a stop codon","Causes a frame-shift that changes every subsequent amino acid","Adds one amino acid while the reading frame after it remains unaltered"],"answer":3,"explanation":"Insertion or deletion of three bases (or multiples of three) adds or removes whole codons, so the reading frame from that point stays the same. Insertion of one or two bases causes a frame-shift.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-39","question":"How many of the following statements about the Human Genome Project are correct?\n(i) The Expressed Sequence Tags (ESTs) approach identifies all the genes expressed as RNA.\n(ii) Sequence annotation means sequencing the whole genome, coding and non-coding, and later assigning functions to different regions.\n(iii) Bacteria and yeast were commonly used as hosts, with BAC and YAC as vectors.\n(iv) The sequence of chromosome 1 was completed only in May 2006.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Sequencing used the automated DNA sequencers based on the method developed by Frederick Sanger.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-40","question":"The coding region of an mRNA, from the start codon AUG up to and including the stop codon, is 999 nucleotides long. How many amino acids will the polypeptide contain?","options":["332","333","331","999"],"answer":0,"explanation":"999 ÷ 3 = 333 codons; the stop codon codes for no amino acid, so 333 − 1 = 332. The trap 333 counts the stop codon.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-41","question":"Assertion (A): AUG has a dual function in the genetic code.\nReason (R): It codes for methionine and also acts as the initiator codon.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: AUG specifies methionine within a polypeptide and also signals the start of translation.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-42","question":"Match the component of a transcription unit or operon with its description.\nList I: (A) Promoter (B) Terminator (C) Structural gene (D) Operator\nList II: (1) Region bounded by the promoter and terminator that is transcribed (2) Located towards the 3' end of the coding strand and defines the end of transcription (3) Binding site for the repressor protein (4) Located towards the 5' end (upstream) and provides the binding site for RNA polymerase","options":["A-2, B-4, C-1, D-3","A-4, B-1, C-2, D-3","A-4, B-2, C-3, D-1","A-4, B-2, C-1, D-3"],"answer":3,"explanation":"The promoter lies upstream and binds RNA polymerase; the terminator lies downstream and ends transcription; the structural gene lies between them; the operator binds the repressor in an operon.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-43","question":"How many of the following statements about repetitive DNA and fingerprinting are correct?\n(i) Satellite DNA forms the bulk of repetitive DNA and appears as a separate peak in density gradient centrifugation.\n(ii) Satellite DNA normally codes for proteins.\n(iii) The size of a VNTR varies from 1 to 2 base pairs.\n(iv) Polymorphism in DNA sequence arises from mutations that are inherited.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (iv) are correct. Satellite DNA does not code for proteins, and the size of a VNTR varies from 0.1 to 20 kb.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-44","question":"Which statement about tRNA is INCORRECT?","options":["tRNA has an amino acid acceptor end","tRNA has an anticodon loop with bases complementary to the codon","The actual structure of tRNA is a compact molecule that looks like an inverted L","There are specific tRNAs for each of the three stop codons"],"answer":3,"explanation":"There are no tRNAs for stop codons. tRNAs are specific for each amino acid, and a special initiator tRNA starts translation.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-45","question":"How many of the following statements about transcription are correct?\n(i) The template strand has the polarity 3' → 5'.\n(ii) The coding strand has the same sequence as the RNA, except that it has thymine in place of uracil.\n(iii) In bacteria, the mRNA must be spliced before it can be translated.\n(iv) In eukaryotes, RNA polymerase I transcribes the rRNAs (28S, 18S and 5.8S).","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iv) are correct. Bacterial mRNA needs no processing, so transcription and translation can occur together in the same compartment.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-46", "question": "In some viruses, such as tobacco mosaic virus, the genetic material is:", "options": ["DNA", "Lipid", "Protein", "RNA"], "answer": 3, "explanation": "Although DNA is the genetic material in most organisms, some viruses such as TMV and QB bacteriophage have RNA as their genetic material.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-47", "question": "DNA is a long polymer of:", "options": ["Deoxyribonucleotides", "Ribonucleotides", "Amino acids", "Monosaccharides only"], "answer": 0, "explanation": "DNA is a long polymer of deoxyribonucleotides, each made of a nitrogenous base, 2'-deoxyribose sugar and a phosphate group. RNA is a polymer of ribonucleotides.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-48", "question": "DNA was first identified as an acidic substance in the nucleus, which he named 'nuclein', by:", "options": ["Rosalind Franklin", "Erwin Chargaff", "Friedrich Meischer", "Frederick Griffith"], "answer": 2, "explanation": "Friedrich Meischer identified DNA in 1869 and named it nuclein. Chargaff later worked out base ratios and Franklin produced X-ray diffraction data.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-49", "question": "Erwin Chargaff observed that, for double-stranded DNA:", "options": ["The ratio of adenine to guanine is always 1", "Uracil equals thymine", "Purines are always twice the pyrimidines", "The ratios of adenine to thymine and of guanine to cytosine are constant and equal to one"], "answer": 3, "explanation": "Chargaff's rule: A/T = 1 and G/C = 1, so purines equal pyrimidines. A/G need not be 1, which is the usual trap.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-50", "question": "The X-ray diffraction data on DNA that helped Watson and Crick propose the double helix were produced by:", "options": ["Meselson and Stahl", "Maurice Wilkins and Rosalind Franklin", "Jacob and Monod", "Hershey and Chase"], "answer": 1, "explanation": "Wilkins and Franklin produced the X-ray diffraction data; Watson and Crick used it, along with Chargaff's base ratios, to build the double helix model in 1953.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-51", "question": "The central dogma, DNA → RNA → protein, was proposed by Francis Crick. In some viruses the flow of information is:", "options": ["From protein to DNA", "In reverse, from RNA to DNA", "From protein to RNA", "Absent altogether"], "answer": 1, "explanation": "In some viruses (retroviruses) the flow is reversed, from RNA to DNA, through reverse transcription. Information never flows back from protein to nucleic acid.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-52", "question": "There is now enough evidence to suggest that the first genetic material was:", "options": ["Lipid", "RNA", "DNA", "Protein"], "answer": 1, "explanation": "RNA was the first genetic material: essential life processes evolved around RNA, which can act both as genetic material and as a catalyst. DNA evolved later from RNA with chemical modifications that made it more stable.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-53", "question": "In a nucleotide, the phosphate group is linked to the pentose sugar through a phosphoester linkage at the:", "options": ["3'-OH of the sugar", "2'-OH of the sugar", "5'-OH of the sugar", "1'-OH of the sugar"], "answer": 2, "explanation": "The nitrogenous base is linked to the 1' carbon by an N-glycosidic bond, and the phosphate is esterified to the 5'-OH. Adjacent nucleotides are then joined by a 3'-5' phosphodiester linkage.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-54", "question": "In Griffith's experiment, which injection killed the mice and yielded live S strain bacteria from their bodies?", "options": ["Heat-killed R strain alone", "A mixture of heat-killed S strain and live R strain", "Heat-killed S strain alone", "Live R strain alone"], "answer": 1, "explanation": "Live R alone and heat-killed S alone did not kill mice. The mixture of heat-killed S and live R killed them, and live S bacteria were recovered, showing that R had been transformed by a 'transforming principle'.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-55", "question": "In bacteria, the RNA polymerase is able to catalyse the initiation of transcription only when it associates transiently with the:", "options": ["Rho (ρ) factor", "Sigma (σ) factor", "Repressor", "Operator"], "answer": 1, "explanation": "The sigma factor helps RNA polymerase initiate transcription, while the rho factor is needed for termination. The repressor and operator belong to the lac operon's control system.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-56", "question": "Before the genetic code was deciphered, tRNA was known as:", "options": ["rRNA", "sRNA (soluble RNA)", "hnRNA", "snRNA"], "answer": 1, "explanation": "tRNA was called sRNA (soluble RNA) before the code was worked out. Its role as an adapter molecule, reading the code on one side and binding amino acids on the other, was postulated by Francis Crick.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-57", "question": "George Gamow argued that if 4 bases must code for 20 amino acids, the code should be made of three nucleotides. The reasoning was that:", "options": ["A doublet code gives only 4² = 16 combinations, while a triplet code gives 4³ = 64", "A single base can code for 20 amino acids", "A triplet code gives exactly 20 combinations", "A doublet code gives 64 combinations"], "answer": 0, "explanation": "With 4 bases, doublets give 16 combinations, too few for 20 amino acids; triplets give 64, more than enough. This is why the code is degenerate.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-58", "question": "In the Hershey–Chase experiment, after infection, blending and centrifugation, radioactivity was found mainly in the bacterial cells (pellet) when the phages had been grown in medium containing:", "options": ["Heavy nitrogen (¹⁵N)", "Radioactive carbon (¹⁴C)", "Radioactive phosphorus (³²P)", "Radioactive sulphur (³⁵S)"], "answer": 2, "explanation": "³²P labels DNA, which entered the bacteria, so the cells became radioactive. With ³⁵S-labelled protein coats, the radioactivity stayed outside in the supernatant, showing DNA is the genetic material.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-59", "question": "In eukaryotes, the heterogeneous nuclear RNA (hnRNA), the precursor of mRNA, is transcribed by:", "options": ["RNA polymerase II", "Reverse transcriptase", "RNA polymerase III", "RNA polymerase I"], "answer": 0, "explanation": "RNA polymerase II transcribes hnRNA. RNA polymerase I makes rRNAs (28S, 18S, 5.8S), and RNA polymerase III makes tRNA, 5S rRNA and snRNAs.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-60", "question": "How many of the following are criteria a molecule must fulfil to act as genetic material?\n(i) It should be able to generate its replica.\n(ii) It should be chemically and structurally stable.\n(iii) It should not allow any change (mutation) at all.\n(iv) It should be able to express itself in the form of Mendelian characters.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iv) are NCERT criteria. (iii) is wrong: genetic material should provide scope for slow changes (mutation) that are required for evolution.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-61", "question": "Match the scientist with the contribution.\nList I: (A) Friedrich Meischer (B) Erwin Chargaff (C) Wilkins and Franklin (D) Francis Crick\nList II: (1) Central dogma of molecular biology (2) X-ray diffraction data of DNA (3) Base ratios A/T and G/C equal to one (4) Identified DNA as nuclein", "options": ["A-4, B-3, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1"], "answer": 0, "explanation": "Meischer named nuclein (1869); Chargaff gave the base ratios; Wilkins and Franklin produced X-ray diffraction data; Crick proposed the central dogma.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-62", "question": "Assertion (A): Viruses having an RNA genome and a short life span mutate and evolve faster.\nReason (R): RNA is unstable and reactive, so it mutates at a faster rate than DNA.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. The 2'-OH makes RNA reactive and easily degradable, so RNA genomes mutate faster, and combined with short life spans this lets RNA viruses evolve rapidly.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-63", "question": "In the reading frame 5'-AUG UUU CCC GGG AAA-3', the first U of the second codon is deleted. The first four codons of the new reading frame are:", "options": ["AUG UUU CCG GGA", "AUG UUC CCC GGG", "AUG UCC CGG GAA", "AUG UUC CCG GGA"], "answer": 3, "explanation": "After the deletion the sequence is AUGUUCCCGGGAAA, read in triplets from AUG as AUG UUC CCG GGA. A one-base deletion shifts the frame from the point of deletion onward (a frameshift).", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-64", "question": "A diploid human cell has 6.6 × 10⁹ base pairs of DNA. If a typical nucleosome contains 200 bp of DNA, the number of nucleosomes in the cell is about:", "options": ["3.3 × 10⁷", "3.3 × 10⁶", "1.32 × 10⁸", "6.6 × 10⁷"], "answer": 0, "explanation": "Number of nucleosomes = 6.6 × 10⁹ ÷ 200 = 3.3 × 10⁷. Dividing by 100 instead of 200 gives the 6.6 × 10⁷ trap.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-65", "question": "Arrange the following in chronological order:\n(i) Hershey–Chase experiment with bacteriophages\n(ii) Griffith's transformation experiment\n(iii) Meischer's identification of nuclein\n(iv) Meselson–Stahl experiment on semiconservative replication", "options": ["(iii), (i), (ii), (iv)", "(ii), (iii), (i), (iv)", "(iii), (ii), (i), (iv)", "(iii), (ii), (iv), (i)"], "answer": 2, "explanation": "Meischer 1869, Griffith 1928, Hershey and Chase 1952, Meselson and Stahl 1958.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-66", "question": "How many of the following statements about the Watson–Crick double helix are correct?\n(i) The sugar-phosphate backbone is on the outside and the bases project inside.\n(ii) The two polynucleotide chains are antiparallel.\n(iii) A purine always pairs with a pyrimidine, giving a uniform distance between the two strands.\n(iv) The two chains are coiled in a left-handed fashion.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iii) are correct. (iv) is wrong: the two chains of B-DNA are coiled in a right-handed fashion.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-67", "question": "Which of the following was NOT one of the goals of the Human Genome Project?", "options": ["Determining the sequence of the 3 billion chemical base pairs of human DNA", "Producing genetically modified human beings with improved genes", "Addressing the ethical, legal and social issues that may arise from the project", "Identifying all the approximately 20,000–25,000 genes in human DNA"], "answer": 1, "explanation": "HGP goals included identifying the genes, sequencing about 3 billion bp, storing the data, improving analysis tools, transferring technology, and addressing ELSI. Producing modified humans was never a goal.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-68", "question": "How many of the following statements about regulation of gene expression are correct?\n(i) In prokaryotes, control of the rate of transcriptional initiation is the predominant site of regulation.\n(ii) The accessibility of the promoter is regulated by accessory proteins interacting with sequences called operators.\n(iii) In eukaryotes, regulation is exerted only at the level of transcription.\n(iv) The lac operon is also under positive regulation, in addition to negative regulation by the repressor.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iv) are correct. (iii) is wrong: in eukaryotes regulation can occur at transcription, processing (splicing), transport of mRNA from nucleus to cytoplasm, and translation.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-69", "question": "Match the type of RNA with its role.\nList I: (A) mRNA (B) tRNA (C) rRNA (D) hnRNA\nList II: (1) Structural and catalytic role in translation (2) Provides the template for translation (3) Primary transcript containing both exons and introns (4) Reads the code and brings specific amino acids", "options": ["A-2, B-4, C-1, D-3", "A-2, B-4, C-3, D-1", "A-4, B-2, C-1, D-3", "A-1, B-4, C-2, D-3"], "answer": 0, "explanation": "mRNA is the template; tRNA reads the code and carries amino acids; rRNA plays structural and catalytic roles; hnRNA is the unprocessed primary transcript containing exons and introns.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-molecular-basis-inheritance-70", "question": "Assertion (A): During transcription, only one strand of a DNA segment is copied into RNA.\nReason (R): If both strands acted as templates, they would produce two complementary RNA molecules that could pair into double-stranded RNA and prevent translation.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Two different RNAs from one segment would complicate the machinery, and being complementary they would form dsRNA, making transcription futile.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-71","question":"Which of the following nitrogenous bases is a purine?","options":["Cytosine","Thymine","Guanine","Uracil"],"answer":2,"explanation":"Adenine and guanine are purines (double-ring bases). Cytosine, thymine and uracil are pyrimidines; thymine occurs only in DNA and uracil only in RNA.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-72","question":"A nitrogenous base linked to a pentose sugar through an N-glycosidic linkage, such as adenosine, is called a:","options":["Nucleotide","Polynucleotide","Nucleosome","Nucleoside"],"answer":3,"explanation":"Base + sugar = nucleoside (adenosine, guanosine, cytidine, uridine). Adding a phosphate through a phosphoester linkage at 5'-OH gives a nucleotide. A nucleosome is a DNA–histone packaging unit.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-73","question":"Two nucleotides in a polynucleotide chain are joined through a:","options":["3'–5' phosphodiester linkage","Peptide bond","N-glycosidic linkage","Hydrogen bond"],"answer":0,"explanation":"The phosphate links the 3'-carbon of one sugar to the 5'-carbon of the next, forming the sugar-phosphate backbone. Hydrogen bonds join bases of the two opposite strands, and N-glycosidic bonds join a base to its sugar.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-74","question":"Thymine, present in DNA but not in RNA, is chemically:","options":["5-methyl uracil","5-methyl cytosine","6-amino purine","A purine with a methyl group"],"answer":0,"explanation":"Thymine is 5-methyl uracil, a pyrimidine. RNA uses uracil in its place; the extra methyl group in thymine is one reason DNA is chemically more stable.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-75","question":"In the Meselson–Stahl experiment, DNA containing ¹⁵N was distinguished from DNA containing ¹⁴N by:","options":["Autoradiography of radioactive ¹⁵N","Centrifugation in a caesium chloride (CsCl) density gradient","Gel electrophoresis according to size","X-ray diffraction"],"answer":1,"explanation":"¹⁵N is a heavy, non-radioactive isotope, so heavy and light DNA were separated by density in a CsCl gradient. Autoradiography is impossible because ¹⁵N is not radioactive.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-76","question":"Taylor and colleagues (1958) showed that DNA in chromosomes also replicates semiconservatively, using:","options":["E. coli and ¹⁵NH₄Cl","Bacteriophage and ³²P","Vicia faba (faba beans) and radioactive thymidine","Neurospora and X-rays"],"answer":2,"explanation":"Taylor used radioactive thymidine to follow new DNA in the chromosomes of Vicia faba. Meselson and Stahl used E. coli and ¹⁵N, and Hershey and Chase used bacteriophage labelled with ³²P and ³⁵S.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-77","question":"DNA-dependent DNA polymerases can catalyse polymerisation:","options":["Only in the 3' → 5' direction","In both directions equally","In either direction, depending on the template","Only in the 5' → 3' direction"],"answer":3,"explanation":"Because polymerisation runs only 5' → 3', the strand whose template runs 3' → 5' is made continuously. The other strand is made discontinuously as Okazaki fragments, which DNA ligase joins.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-78","question":"In eukaryotes, DNA replication takes place during the:","options":["G₁ phase; failure of cell division after it results in aneuploidy","S phase of the cell cycle; failure of cell division after it results in polyploidy","M phase, along with chromosome condensation","G₂ phase, immediately before cytokinesis"],"answer":1,"explanation":"DNA is replicated in the S (synthesis) phase. Replication and cell division must be coordinated: if the cell does not divide after replication, the chromosome sets are doubled, giving polyploidy.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-79","question":"Operons such as lac, trp, ara, his and val are characteristic of gene regulation in:","options":["Eukaryotes only","Viruses only","Prokaryotes","Mitochondria only"],"answer":2,"explanation":"In bacteria, polycistronic structural genes are regulated by a common promoter and regulatory genes in an operon. NCERT lists lac, trp, ara, his and val as examples.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-80","question":"A segment of mRNA reads 5'-AUGGCU-3'. The template strand of DNA that was transcribed to produce it is:","options":["5'-ATGGCT-3'","3'-UACCGA-5'","5'-TACCGA-3'","3'-TACCGA-5'"],"answer":3,"explanation":"The template is complementary and antiparallel to the mRNA, so it reads 3'-TACCGA-5'. 5'-ATGGCT-3' is the coding strand, which matches the mRNA with T in place of U. DNA has no U.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-81","question":"In a transcription unit, the promoter is located towards which end of the structural gene, with reference to the polarity of the coding strand?","options":["5' end (upstream)","3' end (downstream)","In the middle of the structural gene","Inside the terminator"],"answer":0,"explanation":"By convention, the promoter is upstream at the 5' end of the coding strand and provides the binding site for RNA polymerase. The terminator lies downstream at the 3' end and defines where transcription stops.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-82","question":"Assertion (A): In bacteria, translation can often begin well before the mRNA is fully transcribed.\nReason (R): Bacterial mRNA needs no processing to become active, and transcription and translation occur in the same compartment.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Bacteria have no nuclear membrane separating DNA from ribosomes, and their mRNA is not capped, tailed or spliced. Ribosomes can therefore start on the growing transcript, so R explains A.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-83","question":"The untranslated regions (UTRs) of an mRNA are:","options":["Present only at the 5' end and removed before translation","Present at both the 5' end (before the start codon) and the 3' end (after the stop codon), and needed for efficient translation","The introns that are spliced out of hnRNA","Present only in prokaryotic mRNA"],"answer":1,"explanation":"UTRs are additional sequences at both ends that are not translated but are required for efficient translation. Introns are removed during splicing and are not UTRs.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-84","question":"Regulation of the lac operon by the repressor protein is referred to as:","options":["Positive regulation","Translational regulation","Negative regulation","Post-translational regulation"],"answer":2,"explanation":"The repressor switches transcription off by binding the operator; the inducer turns it on by inactivating the repressor. This is negative control. NCERT notes that the lac operon is also under positive regulation.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-85","question":"The genetic code is nearly universal: UUU codes for phenylalanine in bacteria as well as in humans. Exceptions to this rule have been found in:","options":["Bacterial chromosomes and plasmids","All plant nuclear genes","Viral RNA genomes only","Mitochondrial codons and some protozoans"],"answer":3,"explanation":"NCERT notes exceptions to universality in mitochondrial codons and in some protozoans. Bacterial and plant nuclear genes follow the standard code, which is why genes can be expressed across species in biotechnology.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-86","question":"The VNTRs used as probes in DNA fingerprinting belong to which class of repetitive DNA, and what is their size range?","options":["Microsatellites; 1 to 6 bp","Minisatellites; 0.1 to 20 kb","Minisatellites; 100 to 200 kb","Highly repetitive coding DNA; 1 to 2 kb"],"answer":1,"explanation":"VNTRs (variable number tandem repeats) are minisatellites. Their copy number varies between individuals, so their size varies from 0.1 to 20 kb, and this produces the band differences seen in fingerprints.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-87","question":"In the Human Genome Project, sequencing was done with automated DNA sequencers that worked on the principle of a method developed by:","options":["Alec Jeffreys","Har Gobind Khorana","Frederick Sanger","Marshall Nirenberg"],"answer":2,"explanation":"Sanger's method was the basis of the automated sequencers. Alec Jeffreys developed DNA fingerprinting, and Khorana and Nirenberg contributed to deciphering the genetic code.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-88","question":"An allelic sequence variant at a locus is traditionally called a DNA polymorphism when it occurs in the human population at a frequency greater than:","options":["0.5","0.0001","0.25","0.01"],"answer":3,"explanation":"A variant counts as a polymorphism when more than one allele at a locus occurs at a frequency above 0.01 (1%). Polymorphisms arise from heritable mutations, mostly in non-coding DNA, and they are the basis of DNA fingerprinting.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-89","question":"Har Gobind Khorana contributed to deciphering the genetic code mainly by:","options":["Developing a chemical method to synthesise RNA molecules with defined combinations of bases","Discovering the enzyme polynucleotide phosphorylase","Proposing the triplet nature of the code from permutation arguments","Using a cell-free system to translate synthetic poly-U into polyphenylalanine"],"answer":0,"explanation":"Khorana chemically synthesised RNA homopolymers and copolymers of defined sequence. Polynucleotide phosphorylase was the work of Severo Ochoa, the triplet argument came from George Gamow, and the cell-free poly-U experiment was Nirenberg's.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-90","question":"In E. coli, a mutation in the i gene makes the repressor non-functional so that it cannot bind the operator. In the ABSENCE of lactose, this bacterium will:","options":["Transcribe the z, y and a genes continuously (constitutively)","Never express the z, y and a genes, even if lactose is added","Express only the i gene","Transcribe only the z gene"],"answer":0,"explanation":"Without a working repressor, the operator is always free and RNA polymerase transcribes the structural genes whether or not lactose is present. The inducer is needed only to inactivate a functional repressor.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-91","question":"Assertion (A): Even in the absence of lactose, a very low level of expression of the lac operon is present in the cell at all times.\nReason (R): The lac repressor is synthesised only when lactose is present in the medium.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: some permease must always be present, otherwise lactose could not enter the cell to induce the operon. R is false: the repressor is made constitutively from the i gene, all the time.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-92","question":"A DNA sample has base composition A = 20%, G = 30%, T = 25% and C = 25%. The most reasonable conclusion is that the DNA is:","options":["Double-stranded B-DNA","Double-stranded but rich in G–C pairs","Single-stranded","Contaminated with RNA"],"answer":2,"explanation":"Chargaff's rules (A = T and G = C) hold only for double-stranded DNA. Here A ≠ T and G ≠ C, which points to a single-stranded genome, as in bacteriophage φX174. RNA would contain uracil, not thymine.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-93","question":"In one strand of a DNA double helix, (A + G)/(T + C) = 0.5 and (A + T)/(G + C) = 0.4. The corresponding ratios in the complementary strand are:","options":["0.5 and 0.4","2.0 and 2.5","0.5 and 2.5","2.0 and 0.4"],"answer":3,"explanation":"Complementary pairing swaps A with T and G with C. The purine/pyrimidine ratio becomes its reciprocal, 1/0.5 = 2.0, while (A + T)/(G + C) keeps the same value, 0.4, in both strands and in the whole molecule.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-94","question":"E. coli grown for many generations in ¹⁴N medium (light DNA) is transferred to ¹⁵N medium. After three generations, the ratio of hybrid (¹⁵N/¹⁴N) to heavy (¹⁵N/¹⁵N) DNA molecules is:","options":["1 : 1","1 : 3","1 : 7","3 : 1"],"answer":1,"explanation":"Under semiconservative replication, the two original light strands always stay in two hybrid molecules. After 3 generations there are 8 molecules: 2 hybrid and 6 heavy, a 1 : 3 ratio. No fully light molecules remain.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-95","question":"The codon on an mRNA is 5'-GCA-3'. The anticodon on the tRNA that pairs with it, written 5' → 3', is:","options":["5'-CGU-3'","5'-TGC-3'","5'-UGC-3'","5'-GCA-3'"],"answer":2,"explanation":"Codon and anticodon pair antiparallel, so the anticodon is 3'-CGU-5', which reads 5'-UGC-3' when written 5' → 3'. 5'-CGU-3' is the trap of forgetting the reversed polarity, and tRNA contains no T in its anticodon.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-96","question":"The mRNA 5'-GCAUGUUUAAAUGACC-3' is translated starting at the first AUG. How many amino acids will the polypeptide contain?","options":["4","5","2","3"],"answer":3,"explanation":"Reading from the first AUG gives AUG (Met), UUU (Phe), AAA (Lys) and UGA (stop). The stop codon codes for no amino acid, so the product is a tripeptide. The bases before AUG are not translated.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-97","question":"In the coding region of a gene, one base is inserted within the 3rd codon and one base is deleted within the 6th codon. The most likely result is:","options":["Codons 3 to 6 are altered, but the reading frame is restored from the 7th codon onwards","Every codon from the 3rd to the end of the gene is altered","Only the 3rd codon is altered","The protein is unchanged because the number of bases is the same"],"answer":0,"explanation":"The insertion shifts the reading frame from codon 3, and the deletion shifts it back at codon 6. Only codons 3–6 are misread, and downstream codons are read normally. A single insertion or deletion alone would garble every codon after it.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-98","question":"How many of the following statements about the lac operon are correct?\n(i) The z, y and a genes are transcribed as a single polycistronic mRNA.\n(ii) The repressor is synthesised constitutively from the i gene.\n(iii) Lactose acts as the inducer.\n(iv) β-galactosidase hydrolyses lactose into glucose and galactose.\n(v) The repressor binds the promoter and directly destroys RNA polymerase.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i) to (iv) are correct. (v) is false: the repressor binds the operator, which prevents RNA polymerase from transcribing the operon. It does not bind the promoter or destroy the enzyme.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-99","question":"A eukaryotic gene has three exons of 300, 450 and 150 bp, separated by two introns of 500 bp each. The coding sequence starts with the start codon at the beginning of exon 1 and ends with the stop codon at the end of exon 3. The number of amino acids in the polypeptide is:","options":["300","299","633","632"],"answer":1,"explanation":"Introns are spliced out, leaving 300 + 450 + 150 = 900 coding bases, or 300 codons. The last codon is a stop codon, which codes for no amino acid, so the polypeptide has 299 amino acids.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-molecular-basis-inheritance-100","question":"A double-stranded DNA molecule of 1000 base pairs replicates semiconservatively three times. How many new nucleotides are incorporated in total?","options":["16,000","8,000","14,000","6,000"],"answer":2,"explanation":"Three rounds produce 8 molecules, which contain 16 strands of 1000 nucleotides each, or 16,000 nucleotides. Subtracting the 2 original strands (2000 nucleotides) leaves 14,000 new nucleotides.","difficulty":"very-hard","source":"NEET pattern"},
];

export default questions;
